import json
import sys
import hashlib
import re
from decimal import Decimal, getcontext

def round_and_format(value):
    getcontext().prec = 6
    rounded = round(Decimal(str(value)), 6)
    s = str(rounded)
    if '.' in s:
        s = s.rstrip('0').rstrip('.') if '.' in s else s
    return s

def render_template(data, template):
    output = []
    i = 0
    n = len(template)
    while i < n:
        if template.startswith('{{', i):
            j = template.find('}}', i)
            if j == -1:
                raise ValueError("Unclosed placeholder")
            expr = template[i+2:j]
            try:
                value = eval(expr, {'__builtins__': None}, data)
            except Exception as e:
                raise ValueError(f"Invalid expression '{expr}': {e}")
            formatted = round_and_format(value)
            output.append(formatted)
            i = j + 2
        else:
            output.append(template[i])
            i += 1
    return ''.join(output)

def main():
    if len(sys.argv) != 4:
        print("Usage: python render.py <data.json> <template.txt> <output.txt>", file=sys.stderr)
        sys.exit(1)

    data_file = sys.argv[1]
    template_file = sys.argv[2]
    output_file = sys.argv[3]

    try:
        with open(data_file, 'r', encoding='utf-8') as f:
            data = json.load(f)
    except Exception as e:
        print(f"Error reading data file: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        with open(template_file, 'r', encoding='utf-8') as f:
            template = f.read()
    except Exception as e:
        print(f"Error reading template file: {e}", file=sys.stderr)
        sys.exit(1)

    rendered = render_template(data, template)

    try:
        with open(output_file, 'w', encoding='utf-8') as f:
            f.write(rendered)
    except Exception as e:
        print(f"Error writing output file: {e}", file=sys.stderr)
        sys.exit(1)

    byte_count = sys.getsizeof(rendered.encode('utf-8'))

    manifest_file = f"{output_file}.manifest.json"
    try:
        digest = hashlib.sha256(rendered.encode('utf-8')).hexdigest()
        manifest = {
            "template": template_file,
            "byte_count": byte_count,
            "digest": digest
        }
        with open(manifest_file, 'w', encoding='utf-8') as f:
            json.dump(manifest, f, ensure_ascii=False)
    except Exception as e:
        print(f"Error creating manifest file: {e}", file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
    main()

