import json
import sys
import re
import hashlib
from typing import Dict, List, Tuple

def evaluate_expression(expr: str, data: Dict[str, float]) -> float:
    try:
        # Replace identifiers with their values from data
        for key in data:
            expr = expr.replace(key, str(data[key]))
        # Evaluate the expression safely
        return eval(expr, {'__builtins__': None}, {})
    except Exception:
        raise ValueError(f"Invalid expression: {expr}")

def format_result(value: float) -> str:
    rounded = round(value, 6)
    s = "{0:.6f}".format(rounded)
    # Remove trailing zeros and decimal if no fractional part
    s = s.rstrip('0').rstrip('.') if '.' in s else s
    return s

def render_template(template: str, data: Dict[str, float]) -> str:
    def replace_match(match):
        expr = match.group(1)
        try:
            result = evaluate_expression(expr, data)
            return format_result(result)
        except ValueError as e:
            raise ValueError(f"Error evaluating expression '{expr}': {e}")

    # Regex to match placeholders
    pattern = re.compile(r'\{\{([^}]+)\}\}')
    return pattern.sub(replace_match, template)

def compute_digest(file_path: str) -> str:
    with open(file_path, 'rb') as f:
        return hashlib.sha256(f.read()).hexdigest()

def main():
    if len(sys.argv) != 4:
        print("Usage: python render.py <data.json> <template.txt> <output.txt>", file=sys.stderr)
        sys.exit(1)

    data_path = sys.argv[1]
    template_path = sys.argv[2]
    output_path = sys.argv[3]

    try:
        with open(data_path, 'r', encoding='utf-8') as f:
            data = json.load(f)
    except json.JSONDecodeError as e:
        print(f"Error parsing data.json: {e}", file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(f"Error reading data.json: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        with open(template_path, 'r', encoding='utf-8') as f:
            template = f.read()
    except Exception as e:
        print(f"Error reading template.txt: {e}", file=sys.stderr)
        sys.exit(1)

    rendered = render_template(template, data)

    try:
        with open(output_path, 'w', encoding='utf-8') as f:
            f.write(rendered)
    except Exception as e:
        print(f"Error writing output.txt: {e}", file=sys.stderr)
        sys.exit(1)

    manifest_path = f"{output_path}.manifest.json"
    try:
        with open(manifest_path, 'w', encoding='utf-8') as f:
            manifest = {
                "template": template,
                "byte_count": sys.getsizeof(rendered.encode('utf-8')) if rendered else 0,
                "digest": compute_digest(output_path)
            }
            json.dump(manifest, f, ensure_ascii=False, indent=2)
    except Exception as e:
        print(f"Error writing manifest: {e}", file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
    main()
